"""Stage 27 step 5 -- OFFLINE. Renders report.md from raw/all15_result.json, raw/batch4_result.json, raw/batch4_declaration.json, raw/planner_samsung.json. Nothing is requested."""
from __future__ import annotations

import json
from pathlib import Path

STAGE = Path(__file__).resolve().parents[1]
RAW = STAGE / "raw"
all15 = json.loads((RAW / "all15_result.json").read_text(encoding="utf-8"))["cards"]
live = json.loads((RAW / "batch4_result.json").read_text(encoding="utf-8"))
declaration = json.loads((RAW / "batch4_declaration.json").read_text(encoding="utf-8"))
planner = json.loads((RAW / "planner_samsung.json").read_text(encoding="utf-8"))
by_article = {c["article"]: c for c in all15}

VERDICT = {"export_ready": "готова к выгрузке", "export_ready_with_gaps": "готова с пробелами", "needs_verification": "нужна проверка варианта", "not_ready": "не готова"}
LEVEL = {"full_sku": "полный артикул (разметка/заголовок)", "code_in_page_text": "код только в тексте страницы", "base_model": "только базовая модель"}
BASIS = {"exact_code_in_pdf": "точный код назван в PDF", "family_mask_in_pdf": "назван семейный код (маска); пометка «точный код в PDF не назван»",
         "exact_page_link_only": "«связь с моделью подтверждена точной официальной страницей»; точный код в PDF не назван",
         "code_relation_declared_by_page_data": "PDF называет другой код, связь объявлена данными этой же страницы; точный код каталога в PDF не назван",
         "page_tie_not_exact": "не принята: страница подтверждает артикул только текстом", "manual_check_text_not_extractable": "не принята: текст файла не извлекается",
         "not_a_russian_instruction_by_text": "не принята: по тексту не русская", None: "—"}
GAP = {
    "variant_base_model_only": "подтверждена только базовая модель", "variant_code_only_in_page_text": "код найден только в тексте страницы", "photos_not_selected_variant_open": "фото не выбраны (нет привязки к варианту, нужна ручная проверка)",
    "unresolved_conflicts": "нерешённые конфликты значений", "instruction_missing": "инструкции нет (ссылки на странице нет)", "instruction_language_not_russian": "инструкция не на русском",
    "instruction_russian_file_not_obtained": "русский файл не получен (больше лимита 40 МБ)", "instruction_text_not_extractable_manual_check": "текст файла не извлекается: ручная проверка",
    "instruction_tied_by_weaker_page": "инструкция связана страницей без строгого подтверждения артикула", "instruction_exact_code_not_in_pdf": "точный код в PDF не назван (пометка)", "dealer_cross_check_missing": "нет подтверждения дилера",
}


def gaps(items):
    return "; ".join(GAP.get(g, g) for g in items) or "—"


def row(card):
    r = card["readiness"]
    return f"| {card['category']} | {card['article']} | `{card['job_status']}` | {VERDICT[r['verdict']]} | {LEVEL.get(r['page_match_level'], r['page_match_level'])} | {card['facts']['samsung']} | {r['official_photos_selected']}/{r['official_photos']} | {BASIS[r['instruction']['acceptance_basis']]} | {gaps(r['blocking_gaps'])} |"


lines = ["# Stage 27: решения владельца по инструкциям и фото, планировщик, партия 4", ""]
verdicts, statuses = {}, {}
for c in all15:
    verdicts.setdefault(c["readiness"]["verdict"], []).append(c["category"])
    statuses.setdefault(c["job_status"], []).append(c["category"])
budget = live["budget"]
lines += ["## Итог", "",
          f"- Ординарный путь (загрузка Excel → подтверждённая партия → задание по кнопке товара → `worker.run_once()` → выгрузка через веб-маршрут) проверен офлайн на 15 выбранных карточках: задания `done` — {len(statuses.get('done', []))}, `needs_review` — {len(statuses.get('needs_review', []))}; готовность: готовы {len(verdicts.get('export_ready', []))}, с пробелами {len(verdicts.get('export_ready_with_gaps', []))}, нужна проверка варианта {len(verdicts.get('needs_verification', []))}.",
          f"- Партия 4 (посудомоечная машина, сушильная машина, колонка, робот-пылесос — по одному товару) выполнена **с реальными запросами** по заранее объявленному бюджету: потрачено {budget['spent_total']} запросов из {budget['max_total']} (объявлено до первого запроса: {declaration['declared_at']}, старт: {live['started_at']}); остановок и блокировок нет, остановленных хостов нет.",
          "- Три решения владельца применены; общего правила равенства кодов не введено. Доказательство инструкции микроволновой печи из этапа 8.6 подхвачено без повторной загрузки PDF. Samsung добавлен в планировщик: предлагается только по одному выбранному товару на категорию (15 из 1182 строк).",
          "- Каталог, реестр источников и `data/batches.sqlite3` не менялись (см. `protected_hashes_check.json`). Остальные 15 категорий остаются в очереди; массового прогона не было.", ""]

lines += ["## Решение 1: русская инструкция без точного кода в PDF", "",
          "Принимается с пометкой «связь с моделью подтверждена точной официальной страницей; точный код в PDF не назван» только если одновременно: страница показывает полный артикул в разметке или заголовке (не в произвольном тексте) и сама печатает ссылку на файл; текст файла — русская инструкция (не декларация); в тексте не названа противоречащая модель. Проверено в коде и тестами; по карточкам:", "",
          "| Карточка | Что в PDF | Основание | Что сказано в данных страницы |", "|---|---|---|---|"]
for article in ("QE48S85HAEXCE", "VC18M21D0VG/EV", "LS24D300GAIXCI"):
    c = by_article[article]
    i = c["readiness"]["instruction"]
    rel = i["code_relation"] or {}
    what = "ни код каталога, ни код ссылки не названы" if article == "QE48S85HAEXCE" else f"назван только {rel.get('link_model_name')}"
    page = "ссылка на файл напечатана самой страницей с полным артикулом" if article == "QE48S85HAEXCE" else f"`model_name` = {rel.get('page_model_name')}, `model_code` = {rel.get('page_model_code')}"
    lines.append(f"| {c['category']} {article} | {what} | {BASIS[i['acceptance_basis']]} | {page} |")
lines += ["",
          "- **Телевизор**: правило применено (PDF не называет ни одной модели, конфликтующей модели нет, страница с полным артикулом сама ссылается на файл).",
          "- **Пылесос и монитор**: PDF называет другой код (`SC18M21D0VG`, `S24D300GAI`). Я сначала проверил официальные данные: страница в своих данных (`digitalData.product`) объявляет этот код названием модели (`model_name`) рядом с кодом каталога как `model_code`. Документ принят **только** на этом основании, для этой страницы. Если такой связи в данных нет, страница называет другую модель или страница подтверждает код лишь текстом, документ остаётся на проверке (`link_code_relation_unverified`) — это проверено на отрицательных примерах в тестах. Равенство `SC = VC` или `LS = S` нигде не задано.",
          "- Документ хранится с двумя кодами раздельно: модель каталога (`product_model`) и модель, объявленная ссылкой (`support_model`); пометка о принятии записана в названии документа и в выгрузке.", ""]

lines += ["## Решение 2: маска семейства", "",
          "Маска принимается и **всегда** несёт пометку «точный код в PDF не назван» (в названии документа, в готовности как справочный пробел `instruction_exact_code_not_in_pdf`, в листе «Готовность Samsung»). Так помечены: " + ", ".join(f"{c['category']} ({c['readiness']['instruction']['names_family_mask'][0]})" for c in all15 if c["readiness"]["instruction"]["acceptance_basis"] == "family_mask_in_pdf") + ".", ""]

lines += ["## Решение 3: фото", "",
          "Фото не выбираются автоматически, если артикул лишь встречается в произвольном тексте страницы. Выбираются: вся галерея при полном артикуле в разметке/заголовке; при слабой странице — только фото, чей **собственный путь файла** называет ровно код каталога; либо фото, которые подтвердил человек.", "",
          f"- Варочная панель ({by_article['NZ64T3506AK/WT']['article']}): страница слабая, но единственное фото лежит по пути `.../nz64t3506ak-wt/...` — привязано к варианту, выбрано 1/1.",
          f"- Холодильник ({by_article['RB31FERNDSA']['article']}): путь `rb31ferndsa-wt` — это модель с суффиксом, а не код каталога, привязки нет: 0/{by_article['RB31FERNDSA']['readiness']['official_photos']}, нужна ручная проверка.",
          f"- Galaxy A37: путь называет `sm-a376edggskz`, не `SM-A376EZAGINS`: 0/{by_article['SM-A376EZAGINS']['readiness']['official_photos']}.",
          "- Ручное подтверждение проверено: выбор через `POST /products/{id}/photos` снимает пробел «фото не выбраны», сохраняется при повторном задании и не подтверждает сам вариант (вердикт остаётся «нужна проверка варианта»).", ""]

mw = by_article["MS23K3614AK/BW"]
lines += ["## Микроволновая печь: доказательство этапа 8.6", "",
          f"Запись `product_tool/config/samsung_recorded_documents.v1.json` (ссылка, размер 10 572 005 байт и 80 страниц совпадают с `assembly_result.json` этапа 8.6; факты взяты из `content_verification.json`): русская инструкция по тексту, в колонтитулах точный код `MS23K3614AK_BW`, обложка называет семейство `MS23K3614A*`, посторонней модели нет. Адаптер использует запись для той же ссылки и того же артикула и **не скачивает PDF**: запросов на карточку — {mw['requests']['spent']} (только страница). Связь файла со страницей читается по текущей странице. Основание: `{mw['readiness']['instruction']['acceptance_basis']}`, происхождение оценки: `{mw['readiness']['instruction']['assessed_from']}`.", ""]

lines += ["## Планировщик", "",
          f"- Samsung подключён как рабочий маршрут `samsung_official` (тип `selected_one_per_category`): из {planner['samsung_units']} строк каталога `ready_to_run` только {len(planner['ready'])} — по одному выбранному товару на категорию (список — в `product_tool/config/coverage_planner.v1.json`, ключ `selected_products`). Остальные: " + "; ".join(f"{k}: {v}" for k, v in planner["by_status_and_reason"].items() if not k.startswith("ready_to_run")) + ".",
          "- Исполнитель очереди (`coverage/executor.py`) получил Samsung-фабрику с отказывающим по умолчанию транспортом; невыбранная строка останавливается до `run_once()` (`not_selected_one_card_per_category`), запросов нет. Волна D в планировщике больше не обещает «сборку адаптера Samsung».",
          "- Тесты планировщика, где Samsung служил синтетическим примером бренда без маршрута, переведены на синтетический бренд Cudy; ожидания по реальной очереди обновлены.", ""]

lines += ["## Ординарный путь офлайн: статус задания и готовность карточки (15 карточек)", "",
          "| Категория | Артикул | Задание | Готовность | Вариант по странице | Характеристики | Фото | Инструкция | Блокирующие пробелы |", "|---|---|---|---|---|---|---|---|---|"]
lines += [row(c) for c in all15]
lines += ["", "Статус задания — состояние сравнения источников (`done`: полный артикул по разметке/заголовку и нет конфликтов); готовность — отдельная оценка полноты карточки; пробелы не прячутся за `done`. Выгрузка `export/samsung_all15_export.xlsx` содержит лист «Готовность Samsung» с обоими показателями.", ""]

lines += ["## Партия 4: реальные запросы", "",
          f"Объявление: `raw/batch4_declaration.json` (до запросов): не более {declaration['budget']['max_real_requests_total']} запросов, не более {declaration['budget']['max_real_requests_per_product']} на товар, пауза 1,5 с, лимит файла 40 МБ; остановка при 401/403/429 или подтверждённом челлендже на любом хосте Samsung, после каждого задания журнал перечитывается, новое задание не начинается при остановке хоста. Адреса не строились: страница — из официальной карты сайта, файлы — по ссылкам, напечатанным страницей.", "",
          "| Товар | Запросы | Ответы |", "|---|---|---|"]
for index, card in enumerate(live["cards"], start=1):
    entries = [e for e in budget["log"] if e["row"] == str(index)]
    kinds = ", ".join(("карта сайта" if e["url"].endswith(".xml") else "файл инструкции" if "ContentsFile" in e["url"] else "страница товара") for e in entries)
    lines.append(f"| {card['category']} ({card['article']}) | {len(entries)} | {kinds}; все 200 |")
lines += ["", f"Итого {budget['spent_total']} из {budget['max_total']}: карта `da` читалась дважды (окно кэша 10 минут истекло к четвёртому товару), карта `vd` — один раз. Журнал остановок `batch4/workdir/samsung_fetch_log.json` записей о блокировках не содержит.", "",
          "### Результат по товарам (реальный прогон, затем офлайн-повтор после исправления словаря)", "",
          "| Категория | Артикул | Задание (реальный прогон → офлайн-повтор) | Готовность | Вариант | Характеристики | Фото | Инструкция | Блокирующие пробелы |", "|---|---|---|---|---|---|---|---|---|"]
for lc in live["cards"]:
    c = by_article[lc["article"]]
    r = c["readiness"]
    lines.append(f"| {c['category']} | {c['article']} | `{lc['job_status']}` → `{c['job_status']}` | {VERDICT[r['verdict']]} | {LEVEL.get(r['page_match_level'])} | {c['facts']['samsung']} | {r['official_photos_selected']}/{r['official_photos']} | {BASIS[r['instruction']['acceptance_basis']]} | {gaps(r['blocking_gaps'])} |")
dw = by_article["DW60M5050BB/WT"]
lines += ["",
          "- **Посудомоечная машина**: первый файл с пометкой RU в имени (`…RU_UK_KK_UZ_R.pdf`) превысил лимит 40 МБ и получен не полностью; второй (`…KA_TR_EN…`) — английский по тексту, сохранён как английский и **не** засчитан русским. Русской инструкции нет: пробелы «русский файл не получен» и «не на русском», проверка поставлена. В реальном прогоне задание было `needs_review` из-за ложного конфликта «Цвет/материал: Нет» и «Цвет подсветки дисплея»; словарь нормализации расширен, офлайн-повтор даёт `done` (сохранённые в отчёте статусы показывают оба состояния).",
          "- **Робот-пылесос**: страница дважды перечисляет «Размеры (ШxВxГ)» и «Вес» под одинаковыми именами без подписи (робот и станция очистки по позиции). Это конфликт значений внутри одного источника, оставлен человеку намеренно: авто-разметку по позиции я не вводил. Инструкция: русская, названа маска `VR50T95****` (пометка).",
          "- **Сушильная машина**: русская по тексту (в файле ещё казахский), маска `DV16DG8600**` с пометкой, все 18 фото привязаны к коду каталога путём файла.",
          "- **Колонка MX-ST50B**: точный код в PDF, готова без пробелов, кроме подтверждения дилера (запрос дилеру не нужен: недостающих полей нет).", ""]

lines += ["## Что остаётся человеку и решения", "",
          "1. **Посудомоечная машина**: русский файл больше 40 МБ. Предлагаю один объявленный запрос этого файла с лимитом 60 МБ (после вашего слова); либо принять пробел.",
          "2. **Робот-пылесос**: указать, какое значение размеров и веса относится к роботу, какое — к станции (или принять пробел).",
          "3. **Galaxy A37, холодильник, варочная панель** — без изменений: вариант не подтверждён содержимым страницы; у A37 нет инструкции, у холодильника фото без привязки, у варочной панели скан.",
          "4. Остальные 15 категорий очереди — по-прежнему без страниц в картах сайта; сначала нужен объявленный поиск маршрута.", ""]
(STAGE / "report.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
print("report.md", len(lines), "lines")
